// Language Studio Player — the district pacing-guide module for an ELA unit (teacher view).
// Data comes from the lessons API (`module`, `lesson.module_week`), generated by tools/build-bcpss-module-facts.mjs
// from the district Wit & Wisdom guides. Everything shown is printed in the guide or says it is a suggestion.
import { h } from "./studio-core.js";

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const part = (iso) => {
  const [y, m, d] = String(iso).split("-").map(Number);
  return { y, m: MONTHS[m - 1], d };
};

/** "Dec 1 – Mar 4, 2026" from two ISO dates; "" when either is missing. */
export function dateSpan(start, end) {
  if (!start || !end) return "";
  const a = part(start);
  const b = part(end);
  return a.y === b.y
    ? `${a.m} ${a.d} – ${b.m} ${b.d}, ${b.y}`
    : `${a.m} ${a.d}, ${a.y} – ${b.m} ${b.d}, ${b.y}`;
}

/** "Dec 8–12" or "Sep 29 – Oct 3" for one week. */
export function weekSpan(w) {
  if (!w?.start || !w?.end) return w?.label || "";
  const a = part(w.start);
  const b = part(w.end);
  return a.m === b.m ? `${a.m} ${a.d}–${b.d}` : `${a.m} ${a.d} – ${b.m} ${b.d}`;
}

const lessonRange = (r) => (r ? `Wit & Wisdom lessons ${r[0]}–${r[1]}` : "");

function weekRow(w, zero) {
  const span = weekSpan(w);
  return h(
    "li",
    { class: "sm-week" },
    h("b", { class: "sm-week__n" }, `Week ${w.n}`),
    span ? h("span", { class: "sm-week__dates" }, span) : null,
    w.lessons ? h("span", { class: "sm-week__lessons" }, lessonRange(w.lessons)) : null,
    zero.has(w.n) ? h("span", { class: "sm-week__zero" }, "Start Strong (Module 0)") : null,
  );
}

/** The module card for a unit's lessons section. Null when the unit has no district module (Module 4, other subjects). */
export function modulePanel(mod) {
  if (!mod) return null;
  const zero = new Set(mod.module_zero_weeks || []);
  const heading = mod.title ? `Module ${mod.module} · ${mod.title}` : `Module ${mod.module}`;
  const sub = [dateSpan(mod.start, mod.end), mod.writing].filter(Boolean).join(" · ");
  return h(
    "section",
    { class: "sm-panel", "aria-labelledby": "smH" },
    h("p", { class: "sh-eyebrow" }, "District pacing guide · SY 2025–26"),
    h("h3", { id: "smH", class: "sm-title" }, heading),
    sub ? h("p", { class: "sm-sub" }, sub) : null,
    mod.essential_question
      ? h("p", { class: "sm-eq" }, h("b", null, "Essential question: "), mod.essential_question)
      : null,
    h("p", { class: "sm-intro" }, mod.introduction),
    h("p", { class: "sm-eom" }, h("b", null, "End-of-module task: "), mod.end_of_module_task),
    mod.anchor_texts?.length
      ? h(
          "details",
          { class: "sm-more" },
          h("summary", null, `Texts in the guide (${mod.anchor_texts.length})`),
          h("ul", { class: "sm-texts" }, mod.anchor_texts.map((t) => h("li", null, t))),
        )
      : null,
    h(
      "details",
      { class: "sm-more" },
      h("summary", null, `Module weeks (${mod.weeks.length})`),
      h("ol", { class: "sm-weeks" }, mod.weeks.map((w) => weekRow(w, zero))),
    ),
    h(
      "p",
      { class: "sm-note" },
      `Source: ${mod.source}. Lesson companions are placed in weeks as a suggestion, using the words each week's lessons use.`,
    ),
  );
}

/** Short chip for a lesson row: "Suggested week 4 · Dec 22–23". Null when the lesson has no placement. */
export function weekChip(mw) {
  if (!mw) return null;
  const span = weekSpan(mw);
  return h("span", { class: "sl-chip sm-chip" }, `Suggested week ${mw.week}${span ? ` · ${span}` : ""}`);
}

/** One sentence under a lesson's title saying where it sits in the module and why. */
export function weekNote(mw) {
  if (!mw) return null;
  const span = weekSpan(mw);
  const where = `Module ${mw.module}, week ${mw.week}${span ? ` (${span})` : ""}`;
  const why =
    mw.how === "terms"
      ? `that week's lessons use ${mw.terms.map((t) => `“${t}”`).join(", ")}`
      : "no week uses this lesson's words, so it keeps the lessons' order across the module";
  const covers = mw.lessons ? ` That week covers ${lessonRange(mw.lessons)}.` : "";
  return h(
    "p",
    { class: "sm-weeknote" },
    h("b", null, "Suggested for "),
    `${where}: ${why}.${covers}`,
  );
}
